    /**
     * Method to retrieve the Admission via an AdmissionPrimaryKey.
     * @param 	id Long
     * @return 	Admission
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Admission handle( FindAdmissionQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAdmissionId() );
    }
    
    /**
     * Method to retrieve a collection of all Admissions
     *
     * @param	query	FindAllAdmissionQuery 
     * @return 	List<Admission> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Admission> handle( FindAllAdmissionQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAdmission,
 * but only if the id matches
 *
 * @param		entity	Admission
 */
	protected void emitFindAdmission( Admission entity ) {
		LOGGER.info("handling emitFindAdmission" );
		
	    queryUpdateEmitter.emit(FindAdmissionQuery.class,
	                            query -> query.getFilter().getAdmissionId().equals(entity.getAdmissionId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAdmission
	 * 
	 * @param		entity	Admission
	 */
	protected void emitFindAllAdmission( Admission entity ) {
		LOGGER.info("handling emitFindAllAdmission" );
		
	    queryUpdateEmitter.emit(FindAllAdmissionQuery.class,
	                            query -> true,
	                            entity);
	}

